pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Get response data
const data = pm.response.json();
pm.collectionVariables.set("userId", data._id);

// Assertion 2: Verify user ID
pm.test("User ID exists", function () {
    pm.expect(data._id).to.be.a("string").and.not.empty;
});

// Assertion 3: Verify user name
pm.test("User name is correct", function () {
    pm.expect(data.name).to.eql("Postman Tester");
});

// Assertion 4: Verify email
pm.test("User email is correct", function () {
    pm.expect(data.email).to.eql("postmantest@gmail.com");
});

// Assertion 5: Verify JWT token exists
pm.test("JWT token is generated", function () {
    pm.expect(data.token).to.be.a("string").and.not.empty;
});

// Assertion 6: Verify JWT structure
pm.test("JWT has three parts", function () {
    pm.expect(data.token.split(".")).to.have.lengthOf(3);
});

// Save token for TC04
pm.collectionVariables.set("token", data.token);

