// Assertion 2: Verify response is an array
pm.test("Response contains a task list", function () {
    pm.expect(data).to.be.an("array");
});

// Assertion 3: Verify all tasks belong to the logged-in user
pm.test("Tasks belong to the authenticated user", function () {
    const userId = pm.collectionVariables.get("userId");

    data.forEach(function(task) {
        pm.expect(String(task.user)).to.eql(userId);
    });
});

